{"operation":"run_python","code":"from math import prod

def divisors(n):
    divs=[]
    i=1
    while i*i<=n:
        if n%i==0:
            divs.append(i)
            if i*i!=n:
                divs.append(n//i)
        i+=1
    return sorted(divs)

def count_sets_for_P(P):
    divs=[d for d in divisors(P) if d%2==1 and d>2]
    n=len(divs)
    # suffix minimal products for pruning: product of k smallest available from index i
    # We'll do simple DFS with pruning.
    count=0
    examples=[]
    def dfs(i,k,cur,chosen):
        nonlocal count
        if k==0:
            if cur==P:
                count+=1
                examples.append(tuple(chosen))
            return
        if i>=n:
            return
        # Need at least k divisors remaining
        if n-i < k:
            return
        # If current product already too large
        if cur>P:
            return
        # Minimal possible product using k smallest remaining divs
        minprod=cur
        for j in range(i, i+k):
            minprod *= divs[j]
            if minprod > P:
                break
        if minprod > P:
            return
        # Max possible product using k largest remaining divs
        maxprod=cur
        for j in range(n-k, n):
            maxprod *= divs[j]
            if maxprod < P:
                break
        if maxprod < P:
            return
        d=divs[i]
        # choose d if divides P/cur
        if (P//cur) % d == 0:
            dfs(i+1,k-1,cur*d,chosen+[d])
        # skip d
        dfs(i+1,k,cur,chosen)
    dfs(0,5,1,[])
    return count, examples

total=0
all_examples=[]
valid_products=[]
for A in range(1,10):
    for B in range(0,10):
        if A==B:
            continue
        if B%2==0:
            continue
        N=10*A+B
        P=1001*N
        # P is five-digit? N>=10, P>=10010, N<=99, P<=99099 yes
        c,ex=count_sets_for_P(P)
        if c:
            valid_products.append((P,N,c,ex))
        total += c
        all_examples.extend([(P,e) for e in ex])

print("total", total)
print("number of valid products", len(valid_products))
for P,N,c,ex in valid_products:
