{"operation":"run_python","code":"import math

def f_intended(x):      # f(x) = 2x - sin x
    return 2*x - math.sin(x)

def f_printed(x):       # f(x) = 2a - sin x, a = 3 (constant)
    a = 3.0
    return 2*a - math.sin(x)

h = 1e-5
def d1(g, x):  # central first derivative
    return (g(x+h) - g(x-h)) / (2*h)
def d2(g, x):  # central second derivative
    return (g(x+h) - 2*g(x) + g(x-h)) / h**2

print("intended f'(x) numeric vs 2-cos x:")
for x in [0.0, 0.7, 1.3, 2.5]:
    print(x, round(d1(f_intended, x), 6), round(2 - math.cos(x), 6))

print("printed f''(x) numeric vs sin x:")
for x in [0.0, 0.7, 1.3, 2.5]:
    print(x, round(d2(f_printed, x), 6), round(math.sin(x), 6))

print("printed f'(x) numeric vs -cos x:")
for x in [0.0, 0.7, 1.3, 2.5]:
    print(x, round(d1(f_printed, x), 6), round(-math.cos(x), 6))
